/* @author MILO-GAO(高振銘)@2020 */ package page2020;import java.util.ArrayList;import java.util.Arrays;import java.util.LinkedHashMap;import java.util.LinkedHashSet;import java.util.List;import java.util.Map;import java.util.Set;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.Prop;import page2020.util.EmptyUtil;import page2020.view.Content;import page2020.view.Element;import page2020.view.Value;import page2020.view.html5.H5button;public class View extends Element<View, Content<?>> {	private static Logger log = LoggerFactory.getLogger(View.class);	private String path;	private Map<String, String> equivs = new LinkedHashMap<String, String>();	private Set<String> stylesheets = new LinkedHashSet<String>();	private Set<String> scripts = new LinkedHashSet<String>();	private Prop<View, LinkedHashMap<String, String>> selector = new Prop<View, LinkedHashMap<String, String>>();	private List<String> javascripts = new ArrayList<String>();	private Map<String, H5button> buttons = new LinkedHashMap<String, H5button>();	private Set<Class<?>> formClasses = new LinkedHashSet<Class<?>>();	private Set<Class<?>> tableClasses = new LinkedHashSet<Class<?>>();	private Set<String> messages = new LinkedHashSet<String>();	private Boolean es6 = false;	private Boolean babel = false;	private Boolean axios = false;	private Boolean react17 = false;	private Boolean vue2 = false;	private Boolean vue3 = false;	private String[] vueFiles = null;	private String vueLink = null;	private String vueScript = null;	private String[] reactFiles = null;	private String reactLink = null;	private String reactScript = null;	private String[] angularFiles = null;	private String angularLink = null;	private String angularScript = null;	public View equiv(String name, String content) {		if (EmptyUtil.not(name, content)) {			this.equivs.put(name, content);		} else {			log.error("equiv: argument(name, contnet) has empty !");		}		return this;	}	public View stylesheet(String filename) {		if (EmptyUtil.not(filename)) {			this.stylesheets.add(filename);		} else {			log.error("stylesheet: argument(filename) is empty !");		}		return this;	}	public View script(String filename) {		if (EmptyUtil.not(filename)) {			this.scripts.add(filename);		} else {			log.error("script: arguemnt(filename) is empty !");		}		return this;	}	public View selector(String query, Value... values) {		if (EmptyUtil.not(query) && EmptyUtil.not((Object[]) values)) {			LinkedHashMap<String, String> items = this.selector.value(query);			if (items == null) {				items = new LinkedHashMap<String, String>();				this.selector.add(query, items);			}			for (int i=0; i < values.length; i++) {				if (values[i] != null && EmptyUtil.not(values[i].getName(), values[i].getValue())) {					items.put(values[i].getName(), values[i].getValue());				} else {					log.error("selector: argument(values[" + i + "]) has empty !");				}			}		} else {			log.error("selector: argument(query, values) has empty !");		}		return this;	}	public View javascript(String script) {		if (EmptyUtil.not(script)) {			script = script.trim();			if (! script.endsWith(";")) {				script += ";";			}			this.javascripts.add(script);		} else {			log.error("javascript: argument(script) is empty !");		}		return this;	}	public View button(String btnName, H5button button) {		if (EmptyUtil.not(btnName) && button != null) {			this.buttons.put(btnName, button);		} else {			log.error("button: argument(btnName, button) has empty !");		}		return this;	}	public View form(Class<?>... classes) {		if (EmptyUtil.not((Object[]) classes)) {			Arrays.asList(classes).forEach(clazz -> this.formClasses.add(clazz));		} else {			log.error("form: argument(classes) is empty !");		}		return this;	}	public View table(Class<?>... classes) {		if (EmptyUtil.not((Object[]) classes)) {			Arrays.asList(classes).forEach(clazz -> this.tableClasses.add(clazz));		} else {			log.error("table: argument(classes) is empty !");		}		return this;	}	public View message(String code) {		if (EmptyUtil.not(code)) {			this.messages.add(code);		} else {			log.error("message: argument(code) is empty !");		}		return this;	}	public void merge(View view) {		if (! view.getEquivs().isEmpty()) {			view.getEquivs().forEach((key, value) -> this.equivs.put(key, value));		}		if (! view.getStylesheets().isEmpty()) {			view.getStylesheets().forEach(string -> this.stylesheets.add(this.path + string));		}		if (! view.getScripts().isEmpty()) {			view.getScripts().forEach(string -> this.scripts.add(this.path + string));		}		int count = view.getSelector().count();		if (count > 0) {			for (int i=0; i < count; i++) {				this.selector.add(view.getSelector().key(i), view.getSelector().value(i));			}		}		if (! view.getJavascripts().isEmpty()) {			this.javascripts.addAll(view.getJavascripts());		}		this.es6 = view.getEs6();		this.babel = view.getBabel();		this.axios = view.getAxios();		this.vue2 = view.getVue2();		this.vue3 = view.getVue3();		if (EmptyUtil.not(this.vueFiles = view.getVueFiles())) {			StringBuilder sbLink = new StringBuilder()				.append("<link href='" + this.path + this.vueFiles[0] + "' rel='preload' as='style'>")				.append("<link href='" + this.path + this.vueFiles[1] + "' rel='preload' as='script'>")				.append("<link href='" + this.path + this.vueFiles[2] + "' rel='preload' as='script'>")				.append("<link href='" + this.path + this.vueFiles[0] + "' rel='stylesheet'>");			StringBuilder sbScript = new StringBuilder()				.append("<script src='./" + this.path + this.vueFiles[2] + "'></script>")				.append("<script src='./" + this.path + this.vueFiles[1] + "'></script>");			this.vueLink = sbLink.toString();			this.vueScript = sbScript.toString();		}		this.react17 = view.getReact17();		if (EmptyUtil.not(this.reactFiles = view.getReactFiles())) {			StringBuilder sbLink = new StringBuilder();			sbLink.append("<link rel='stylesheet' href='" + this.path + this.reactFiles[0] + "'>");			if (this.reactFiles.length == 5) {				sbLink.append("<link rel='stylesheet' href='" + this.path + this.reactFiles[4] + "'>");			}			this.reactLink = sbLink.toString();			StringBuilder sbScript = new StringBuilder();			for (int i=1; i <= 3; i++) {				sbScript.append("<script src='./" + this.path + this.reactFiles[i] + "'></script>");			}			this.reactScript = sbScript.toString();		}		if (EmptyUtil.not(this.angularFiles = view.getAngularFiles())) {			this.angularLink = "<link rel='stylesheet' href='" + this.path + this.angularFiles[0] + "'>";			StringBuilder sbScript = new StringBuilder();			for (int i=1; i <= 3; i++) {				sbScript.append("<script src='./" + this.path + this.angularFiles[i] + "' defer></script>");			}			this.angularScript = sbScript.toString();		}				if (! view.getClassSet().isEmpty()) {			view.getClassSet().forEach(string -> super.getClassSet().add(string));		}		if (! view.getStyleMap().isEmpty()) {			view.getStyleMap().forEach((key, value) -> super.getStyleMap().put(key, value));		}		if (! view.getAttrSet().isEmpty()) {			view.getAttrSet().forEach(string -> super.getAttrSet().add(string));		}		if (! view.getAttrMap().isEmpty()) {			view.getAttrMap().forEach((key, value) -> super.getAttrMap().put(key, value));		}		if (! view.getDataMap().isEmpty()) {			view.getDataMap().forEach((key, value) -> super.getDataMap().put(key, value));		}		if (! view.getMessages().isEmpty()) {			view.getMessages().forEach(code -> this.messages.add(code));		}	}	public View es6() {		this.es6 = Boolean.TRUE;		return this;	}	public View babel() {		this.babel = Boolean.TRUE;		return this;	}	public View axios() {		this.axios = Boolean.TRUE;		return this;	}	public View react17() {		this.react17 = Boolean.TRUE;		return this;	}	public View vue2() {		this.vue2 = Boolean.TRUE;		return this;	}	public View vue3() {		this.vue3 = Boolean.TRUE;		return this;	}	public View vueLink(String path, String css, String app, String chunk) {		css = path + "/dist/css/app." + css + ".css";		app = path + "/dist/js/app." + app + ".js";		chunk = path + "/dist/js/chunk-vendors." + chunk + ".js";		this.vueFiles = new String[] { css, app, chunk };			return this;	}	public View reactLink(String path, String css, String two, String main, String runtime) {		css = path + "/static/css/main." + css + ".chunk.css";		two = path + "/static/js/2." + two + ".chunk.js";		main = path + "/static/js/main." + main + ".chunk.js";		runtime = path + "/static/js/runtime-main." + runtime + ".js";		this.reactFiles = new String[] { css, runtime, two, main };				return this;	}	public View reactLink(String path, String css2, String css, String two, String main, String runtime) {		css2 = path + "/static/css/2." + css2 + ".chunk.css";		css = path + "/static/css/main." + css + ".chunk.css";		two = path + "/static/js/2." + two + ".chunk.js";		main = path + "/static/js/main." + main + ".chunk.js";		runtime = path + "/static/js/runtime-main." + runtime + ".js";		this.reactFiles = new String[] { css, runtime, two, main, css2 };				return this;	}	public View angularLink(String path, String main, String polyfills, String runtime, String css) {		main = path + "/main." + main + ".js";		polyfills = path + "/polyfills." + polyfills + ".js";		runtime = path + "/runtime." + runtime + ".js";		css = path + "/styles." + css + ".css";		this.angularFiles = new String[] { css, runtime, polyfills, main };				return this;	}	@Override	public View copy() {		View view = super.copy();		view.setEquivs(new LinkedHashMap<String, String>(this.equivs));		view.setStylesheets(new LinkedHashSet<String>(this.stylesheets));		view.setScripts(new LinkedHashSet<String>(this.scripts));		view.setSelector(new Prop<View, LinkedHashMap<String, String>>());		view.getSelector().getData().putAll(this.getSelector().getData());		view.setJavascripts(new ArrayList<String>(this.javascripts));		if (! this.buttons.isEmpty()) {			Map<String, H5button> buttons = new LinkedHashMap<String, H5button>();			this.buttons.forEach((name, button) -> {				buttons.put(name, button);			});			view.setButtons(buttons);		}		view.setFormClasses(new LinkedHashSet<Class<?>>(this.formClasses));		view.setTableClasses(new LinkedHashSet<Class<?>>(this.tableClasses));		view.setMessages(new LinkedHashSet<String>(this.messages));		return view;	}	public String getPath() {		return path;	}	public void setPath(String path) {		this.path = path;	}	public Map<String, String> getEquivs() {		return equivs;	}	public void setEquivs(Map<String, String> equivs) {		this.equivs = equivs;	}	public Set<String> getStylesheets() {		return stylesheets;	}	public void setStylesheets(Set<String> stylesheets) {		this.stylesheets = stylesheets;	}	public Set<String> getScripts() {		return scripts;	}	public void setScripts(Set<String> scripts) {		this.scripts = scripts;	}	public Prop<View, LinkedHashMap<String, String>> getSelector() {		return selector;	}	public void setSelector(Prop<View, LinkedHashMap<String, String>> selector) {		this.selector = selector;	}	public List<String> getJavascripts() {		return javascripts;	}	public void setJavascripts(List<String> javascripts) {		this.javascripts = javascripts;	}	public Map<String, H5button> getButtons() {		return buttons;	}	public void setButtons(Map<String, H5button> buttons) {		this.buttons = buttons;	}	public Set<Class<?>> getFormClasses() {		return formClasses;	}	public void setFormClasses(Set<Class<?>> formClasses) {		this.formClasses = formClasses;	}	public Set<Class<?>> getTableClasses() {		return tableClasses;	}	public void setTableClasses(Set<Class<?>> tableClasses) {		this.tableClasses = tableClasses;	}	public Set<String> getMessages() {		return messages;	}	public void setMessages(Set<String> messages) {		this.messages = messages;	}	public Boolean getEs6() {		return es6;	}	public void setEs6(Boolean es6) {		this.es6 = es6;	}	public Boolean getBabel() {		return babel;	}	public void setBabel(Boolean babel) {		this.babel = babel;	}	public Boolean getAxios() {		return axios;	}	public void setAxios(Boolean axios) {		this.axios = axios;	}	public Boolean getReact17() {		return react17;	}	public void setReact17(Boolean react17) {		this.react17 = react17;	}	public Boolean getVue2() {		return vue2;	}	public void setVue2(Boolean vue2) {		this.vue2 = vue2;	}	public Boolean getVue3() {		return vue3;	}	public void setVue3(Boolean vue3) {		this.vue3 = vue3;	}	public String[] getVueFiles() {		return vueFiles;	}	public void setVueFiles(String[] vueFiles) {		this.vueFiles = vueFiles;	}	public String getVueLink() {		return vueLink;	}	public void setVueLink(String vueLink) {		this.vueLink = vueLink;	}	public String getVueScript() {		return vueScript;	}	public void setVueScript(String vueScript) {		this.vueScript = vueScript;	}	public String[] getReactFiles() {		return reactFiles;	}	public void setReactFiles(String[] reactFiles) {		this.reactFiles = reactFiles;	}	public String getReactLink() {		return reactLink;	}	public void setReactLink(String reactLink) {		this.reactLink = reactLink;	}	public String getReactScript() {		return reactScript;	}	public void setReactScript(String reactScript) {		this.reactScript = reactScript;	}	public String[] getAngularFiles() {		return angularFiles;	}	public void setAngularFiles(String[] angularFiles) {		this.angularFiles = angularFiles;	}	public String getAngularLink() {		return angularLink;	}	public void setAngularLink(String angularLink) {		this.angularLink = angularLink;	}	public String getAngularScript() {		return angularScript;	}	public void setAngularScript(String angularScript) {		this.angularScript = angularScript;	}}